INSERT INTO questions (id, content, correct_answer, difficulty, options, score, type, knowledge_point_id, analysis)
VALUES
  (91011, '下列关于boolean类型的说法，正确的是哪一项？', 'D', '中等', JSON_ARRAY('boolean默认值是null', 'boolean可以与int自动互转', 'boolean占用4字节是语法规定', 'boolean只有true和false两个取值'), 2, 'SINGLE_CHOICE', 9001, 'Java语言层面上boolean表示真值类型，只能取true或false。'),
  (91012, '局部变量在Java中使用前必须满足什么条件？', '先完成显式初始化', '中等', NULL, 3, 'SHORT_ANSWER', 9001, '局部变量不会像成员变量那样自动获得默认值，使用前必须显式赋值。'),
  (91013, 'char类型在Java中可以直接表示Unicode字符。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9001, 'char是16位Unicode字符类型，可表示基本多文种平面中的字符。'),
  (91014, '下列哪项能够构成方法重载？', 'A', '中等', JSON_ARRAY('方法名相同但参数列表不同', '方法名不同但返回值相同', '方法名相同但只有返回值不同', '方法名相同且参数完全相同'), 2, 'SINGLE_CHOICE', 9001, 'Java方法重载依赖参数列表差异，而不是仅依赖返回值。'),
  (91015, '请说明this关键字在实例方法中的常见用途。', '引用当前对象并区分成员变量与局部变量', '中等', NULL, 4, 'SHORT_ANSWER', 9001, 'this常用于访问当前对象成员，或在同名场景下区分成员变量与局部变量。'),

  (91016, '抽象类可以包含已经实现的普通方法。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9002, '抽象类既可以声明抽象方法，也可以提供已实现的方法。'),
  (91017, '接口与抽象类相比，更适合描述什么？', '行为规范', '中等', NULL, 3, 'FILL_BLANK', 9002, '接口更强调对外能力约定，抽象类更适合抽取公共状态和基础实现。'),
  (91018, '下列哪项最能体现多态？', 'C', '中等', JSON_ARRAY('子类不能重写父类方法', '对象创建时必须使用Object类型', '父类引用在运行时指向子类对象并调用重写方法', '一个类只能有一个构造方法'), 2, 'SINGLE_CHOICE', 9002, '多态的核心是统一接口下的不同实现，运行时调用具体子类的重写逻辑。'),
  (91019, '封装的直接价值之一是降低内部实现对外部调用者的暴露程度。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9002, '封装通过访问控制和公开接口隔离实现细节。'),
  (91020, '请简述继承在面向对象设计中的主要作用。', '复用和扩展已有类的属性与行为', '中等', NULL, 4, 'SHORT_ANSWER', 9002, '继承可以基于已有类构建更具体的子类，同时保留并扩展原有能力。'),

  (91021, 'Set接口的一个典型特征是什么？', '元素不允许重复', '中等', NULL, 2, 'FILL_BLANK', 9003, 'Set强调唯一性，不保证像List那样允许重复元素。'),
  (91022, 'ArrayList底层通常基于动态数组实现。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9003, 'ArrayList以数组为基础，擅长随机访问。'),
  (91023, '在需要通过键快速查找值的场景中，通常优先考虑哪种接口？', 'C', '中等', JSON_ARRAY('List', 'Set', 'Map', 'Deque'), 2, 'SINGLE_CHOICE', 9003, 'Map以键值对形式组织数据，适合按键检索。'),
  (91024, 'LinkedList相较ArrayList更适合哪类操作？', '频繁插入和删除中间元素', '中等', NULL, 3, 'SHORT_ANSWER', 9003, '链表结构更适合中间节点插删，但随机访问通常不如数组结构。'),
  (91025, 'Hashtable允许使用null作为key。', '错误', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9003, 'Hashtable不允许null key和null value。'),

  (91108, '主键字段的一个关键要求是什么？', '取值唯一且不能为空', '中等', NULL, 2, 'SHORT_ANSWER', 9011, '主键需要唯一标识记录，因此必须唯一且非空。'),
  (91109, '关系模型中，外键的核心作用是维护表之间的参照完整性。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9011, '外键通过引用另一表的主键或唯一键来建立和约束关系。'),
  (91110, '如果要筛选聚合后的分组结果，应优先使用哪个关键字？', 'HAVING', '中等', NULL, 2, 'FILL_BLANK', 9012, 'HAVING用于过滤聚合后的分组结果。'),
  (91111, 'LEFT JOIN的特点是保留左表全部记录，即使右表没有匹配项。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9012, '左连接会完整保留左侧记录，右侧匹配不到时返回空值。'),
  (91112, '下列哪项最适合描述GROUP BY的作用？', 'B', '中等', JSON_ARRAY('按主键删除重复行', '按照指定列对记录分组以便聚合统计', '把多张表合并成一张表结构', '自动创建索引'), 2, 'SINGLE_CHOICE', 9012, 'GROUP BY通常配合聚合函数进行统计分析。'),
  (91113, '请简述COUNT(*)与COUNT(列名)的一个常见区别。', 'COUNT(*)统计所有行，COUNT(列名)通常忽略该列为NULL的行', '困难', NULL, 4, 'SHORT_ANSWER', 9012, 'COUNT(*)关注行数，COUNT(列名)通常只统计该列非空值。'),
  (91114, '事务的一致性强调事务执行前后数据应满足既定约束。', '正确', '困难', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9013, '一致性要求事务不会破坏业务规则和完整性约束。'),
  (91115, '可重复读主要用来减少哪类并发现象？', '不可重复读', '困难', NULL, 3, 'FILL_BLANK', 9013, '可重复读保证同一事务中多次读取同一记录结果一致。'),
  (91116, '下列哪项最能体现事务的原子性？', 'A', '困难', JSON_ARRAY('一组操作要么全部成功要么全部失败回滚', '多个事务可以随意看到彼此未提交数据', '事务执行后自动创建索引', '事务只能包含一条SQL'), 2, 'SINGLE_CHOICE', 9013, '原子性强调事务是不可再分的最小执行单元。'),

  (91207, '微服务拆分时，常见的边界划分依据是什么？', '业务领域边界', '中等', NULL, 3, 'SHORT_ANSWER', 9021, '服务划分通常围绕业务能力和领域边界，而不是简单按技术层拆分。'),
  (91208, '分布式链路追踪中的traceId通常用于标识一次完整请求链路。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9021, 'traceId用于把跨服务调用串联成同一次请求上下文。'),
  (91209, '服务实例注册到注册中心后，消费者通常通过什么信息完成调用定位？', '服务名和实例元数据', '中等', NULL, 3, 'SHORT_ANSWER', 9022, '服务发现通常先按服务名查询，再结合实例地址、端口和状态进行调用。'),
  (91210, '注册中心中健康检查信息的主要价值是什么？', 'B', '中等', JSON_ARRAY('统一编译Java代码', '帮助剔除不可用实例，提升调用成功率', '替代消息队列', '直接生成前端页面'), 2, 'SINGLE_CHOICE', 9022, '健康检查可用于发现故障实例并避免继续路由流量。'),
  (91211, '网关中的路径重写常用于将外部访问路径转换为下游服务可识别的路径。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9023, '路径重写能让统一入口和内部服务路径解耦。'),
  (91212, '限流在API网关中的核心目标是什么？', '保护系统在高并发下保持稳定', '中等', NULL, 3, 'SHORT_ANSWER', 9023, '限流可以控制请求速率，避免下游被突发流量压垮。'),
  (91213, '如果配置中心支持动态刷新，通常意味着什么？', '部分配置变更后可在运行期生效', '中等', NULL, 3, 'SHORT_ANSWER', 9024, '动态刷新减少了改配置必须整体重启服务的成本。'),
  (91214, '配置中心的环境隔离有助于避免开发、测试、生产配置相互混用。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9024, '环境隔离能降低误用配置带来的运行风险。'),

  (91305, '按需自助服务是云计算的重要特征之一。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9031, '用户可以按需申请资源而不必人工逐次介入。'),
  (91306, '资源池化在云计算中意味着什么？', '底层资源被统一管理并按需分配给多个租户', '中等', NULL, 3, 'SHORT_ANSWER', 9031, '资源池化强调共享基础设施并通过抽象层实现灵活调度。'),
  (91307, '容器与传统虚拟机相比，哪项说法更合理？', 'B', '中等', JSON_ARRAY('容器必须独占一套完整客户机操作系统', '容器通常共享宿主机内核，因此更轻量', '容器不支持镜像分发', '虚拟机不能做资源隔离'), 2, 'SINGLE_CHOICE', 9032, '容器共享宿主机内核，因此通常启动更快、开销更小。'),
  (91308, '镜像是容器运行环境及应用内容的静态封装。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9032, '镜像保存应用运行所需文件和基础环境，是容器实例化的基础。'),
  (91309, 'SaaS更偏向于向最终用户直接提供可使用的软件能力。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9033, 'SaaS面向直接使用软件的用户，PaaS则更偏向开发和部署平台。'),
  (91310, '如果企业需要直接管理操作系统与中间件，通常更接近哪类服务模式？', 'IaaS', '中等', NULL, 3, 'FILL_BLANK', 9033, 'IaaS为用户提供基础设施层资源，用户仍需管理较多上层环境。'),

  (91405, '顺序表随机访问效率通常较高的主要原因是什么？', '存储空间连续，可按下标直接定位', '中等', NULL, 3, 'SHORT_ANSWER', 9041, '连续存储支持通过地址偏移快速访问指定元素。'),
  (91406, '链表插入新节点时通常不需要整体移动大量元素。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9041, '链表通过修改指针关系完成插入，避免了顺序表大规模搬移。'),
  (91407, '栈最典型的操作原则是什么？', '后进先出', '中等', NULL, 2, 'FILL_BLANK', 9042, '栈顶后入先出，是递归和函数调用的重要抽象。'),
  (91408, '循环队列的一个常见目的是什么？', '提高数组存储空间的复用率', '中等', NULL, 3, 'SHORT_ANSWER', 9042, '循环队列通过首尾回绕避免普通顺序队列前部空间浪费。'),
  (91409, '冒泡排序在最坏情况下的时间复杂度是O(n^2)。', '正确', '中等', JSON_ARRAY('正确', '错误'), 2, 'TRUE_FALSE', 9043, '冒泡排序和插入排序在最坏情况下都可能达到平方级复杂度。'),
  (91410, '下列哪种排序算法平均情况下通常具有O(n log n)复杂度？', 'C', '中等', JSON_ARRAY('冒泡排序', '选择排序', '快速排序', '顺序查找'), 2, 'SINGLE_CHOICE', 9043, '快速排序平均复杂度通常为O(n log n)，但最坏情况可能退化。')
ON DUPLICATE KEY UPDATE
  content = VALUES(content),
  correct_answer = VALUES(correct_answer),
  difficulty = VALUES(difficulty),
  options = VALUES(options),
  score = VALUES(score),
  type = VALUES(type),
  knowledge_point_id = VALUES(knowledge_point_id),
  analysis = VALUES(analysis);
